import React, { useEffect, useState } from 'react';
import { LifeBuoy } from 'lucide-react';
import { db, appId } from '../firebase';
import { collection, query, where, onSnapshot, doc, setDoc, addDoc, Timestamp } from 'firebase/firestore';
import InputField from '../components/InputField';
import LoadingSpinner from '../components/LoadingSpinner';
import LoadingSpinnerSmall from '../components/LoadingSpinnerSmall';

const SupportPage = ({ user }) => {
  const [queries, setQueries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [newMessage, setNewMessage] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const isExtensionOfficer = user?.role === 'extension_officer';

  useEffect(() => {
    if (!db || !user) { setLoading(false); return; }

    const queriesColRef = collection(db, `/artifacts/${appId}/public/data/extensionQueries`);
    const q = isExtensionOfficer
      ? query(queriesColRef)
      : query(queriesColRef, where("userId", "==", user.uid));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const queriesData = snapshot.docs.map(docSnap => ({
        id: docSnap.id,
        ...docSnap.data()
      })).sort((a, b) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0));
      setQueries(queriesData);
      setLoading(false);
    }, (error) => {
      console.error("Error fetching extension queries: ", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [user, isExtensionOfficer]);

  const handleSubmitQuery = async (e) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    setIsSubmitting(true);
    try {
      const queriesColRef = collection(db, `/artifacts/${appId}/public/data/extensionQueries`);
      await addDoc(queriesColRef, {
        userId: user.uid,
        userName: user.displayName || 'Anonymous',
        queryText: newMessage,
        status: 'new',
        answerText: null,
        createdAt: Timestamp.now()
      });
      setNewMessage('');
    } catch (error) {
      console.error("Error submitting query:", error);
    }
    setIsSubmitting(false);
  };

  const handleAddAnswer = async (queryId, answerText) => {
    if (!answerText.trim()) return;
    const queryDocRef = doc(db, `/artifacts/${appId}/public/data/extensionQueries`, queryId);
    try {
      await setDoc(queryDocRef, {
        answerText: answerText,
        status: 'answered',
        answeredAt: Timestamp.now()
      }, { merge: true });
    } catch (error) {
      console.error("Error adding answer:", error);
    }
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="max-w-4xl mx-auto p-6 bg-white dark:bg-gray-800 rounded-xl shadow-2xl border border-gray-200 dark:border-gray-700">
        <div className="flex items-center mb-6">
          <LifeBuoy className="w-10 h-10 text-[#1C5D57] mr-3" />
          <div>
            <h1 className="text-3xl font-bold text-[#0B3C49] dark:text-white">Support Center</h1>
            <p className="text-sm text-gray-600 dark:text-gray-400">
              {isExtensionOfficer
                ? 'Manage and respond to farmer queries.'
                : 'Ask questions and get advice from extension officers.'}
            </p>
          </div>
        </div>

        {/* Query Form for Farmers */}
        {!isExtensionOfficer && (
          <form onSubmit={handleSubmitQuery} className="mb-8 p-4 border border-gray-200 dark:border-gray-700 rounded-lg">
            <h2 className="text-xl font-semibold text-gray-800 dark:text-gray-100 mb-2">Ask a Question</h2>
            <InputField
              as="textarea"
              label="Your Question (in English, Swahili, or Kikamba)"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder="Type your question here..."
              rows={4}
            />
            <button type="submit" disabled={isSubmitting}
              className={`mt-3 bg-[#CE6D63] hover:bg-red-700 text-white font-semibold py-2 px-6 rounded-lg shadow`}>
              {isSubmitting ? <LoadingSpinnerSmall /> : 'Submit Query'}
            </button>
          </form>
        )}

        {/* Query List */}
        <div className="space-y-4">
          <h2 className="text-2xl font-semibold text-gray-800 dark:text-gray-100 border-b pb-2">
            {isExtensionOfficer ? "All Farmer Queries" : "Your Query History"}
          </h2>

          {loading ? (
            <LoadingSpinner message="Loading queries..." />
          ) : queries.length === 0 ? (
            <p className="text-gray-500 dark:text-gray-400">No queries found.</p>
          ) : (
            queries.map(q => (
              <QueryCard key={q.id} query={q} isOfficer={isExtensionOfficer} onAddAnswer={handleAddAnswer} />
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const QueryCard = ({ query, isOfficer, onAddAnswer }) => {
  const [answer, setAnswer] = useState('');
  const [isReplying, setIsReplying] = useState(false);

  const statusStyles = {
    new: 'text-blue-600 bg-blue-100 dark:bg-blue-900/50 dark:text-blue-300',
    answered: 'text-green-600 bg-green-100 dark:bg-green-900/50 dark:text-green-300',
  }[query.status] || 'text-gray-500';

  const handleReply = async () => {
    setIsReplying(true);
    await onAddAnswer(query.id, answer);
    setIsReplying(false);
    setAnswer('');
  };

  return (
    <div className="p-4 border rounded-lg bg-gray-50 dark:bg-gray-700/50 border-gray-200 dark:border-gray-600">
      <div className="flex justify-between items-start">
        <div>
          <p className="font-semibold text-gray-800 dark:text-gray-100">
            {isOfficer ? `Query from ${query.userName}` : 'Your Query:'}
          </p>
          <p className="text-gray-600 dark:text-gray-300 whitespace-pre-wrap">{query.queryText}</p>
          <p className="text-xs text-gray-400 mt-1">
            {query.createdAt ? new Date(query.createdAt.seconds * 1000).toLocaleString() : '...'}
          </p>
        </div>
        <span className={`px-2 py-1 text-xs font-medium rounded-full capitalize ${statusStyles}`}>
          {query.status}
        </span>
      </div>

      {query.status === 'answered' && (
        <div className="mt-3 pt-3 border-t border-gray-200 dark:border-gray-600">
          <p className="font-semibold text-[#1C5D57] dark:text-green-300">Answer:</p>
          <p className="text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{query.answerText}</p>
          {query.answeredAt && (
            <p className="text-xs text-gray-400 mt-1">Answered on: {new Date(query.answeredAt.seconds * 1000).toLocaleString()}</p>
          )}
        </div>
      )}

      {isOfficer && query.status !== 'answered' && (
        <div className="mt-3 pt-3 border-t border-gray-200 dark:border-gray-600">
          <InputField
            as="textarea"
            label="Your Answer"
            value={answer}
            onChange={(e) => setAnswer(e.target.value)}
            placeholder="Type your response here..."
            rows={3}
          />
          <button onClick={handleReply} disabled={isReplying}
            className={`mt-2 bg-[#1C5D57] text-white font-semibold px-4 py-2 rounded`}>
            {isReplying ? <LoadingSpinnerSmall /> : 'Submit Answer'}
          </button>
        </div>
      )}
    </div>
  );
};

export default SupportPage;
